WITH order_summary AS (SELECT order_id, SUM(CASE WHEN status = 'DELIVERED' THEN 1 ELSE 0 END) AS delivered_count, MIN(cost) AS min_cost FROM shipments WHERE status <> 'RETURNED' GROUP BY order_id) SELECT o.customer_id, o.discount, os.delivered_count, os.min_cost FROM orders o INNER JOIN order_summary os ON o.id = os.order_id WHERE os.min_cost > 76 ORDER BY os.delivered_count DESC;
